CREATE TABLE dataset_imports(id BIGSERIAL PRIMARY KEY,filename VARCHAR(255),object_key VARCHAR(500),status VARCHAR(30) NOT NULL,total_records INT DEFAULT 0,processed_records INT DEFAULT 0,added_records INT DEFAULT 0,duplicate_records INT DEFAULT 0,rejected_records INT DEFAULT 0,failed_records INT DEFAULT 0,embedding_provider VARCHAR(100),embedding_model VARCHAR(150),uploaded_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);CREATE INDEX idx_dataset_status ON dataset_imports(status);